{
  "title": "Weekend Trip Todos",
  "body": "<div id='app'>
  <h2>Weekend Trip Todos</h2>
  <div class='input-row'>
    <input id='new-todo' placeholder='Add a todo...' />
    <button id='add-btn' type='button'>Add</button>
  </div>
  <ul id='todo-list'></ul>
  <p id='count'></p>
</div>",
  "css": "body { font-family: system-ui, sans-serif; background: #f8fafc; margin: 0; padding: 16px; }
#app { max-width: 420px; margin: 0 auto; background: white; border-radius: 16px; box-shadow: 0 10px 25px rgba(0,0,0,0.05); padding: 20px; }
h2 { margin-top: 0; }
.input-row { display: flex; gap: 8px; margin-bottom: 12px; }
#new-todo { flex: 1; padding: 10px 12px; border: 1px solid #d1d5db; border-radius: 8px; font-size: 14px; }
#add-btn { padding: 10px 14px; background: #2563eb; color: white; border: none; border-radius: 8px; cursor: pointer; }
#add-btn:hover { background: #1d4ed8; }
ul { list-style: none; padding: 0; margin: 0; }
li { display: flex; align-items: center; gap: 8px; padding: 10px 0; border-bottom: 1px solid #e5e7eb; }
li.done .todo-text { text-decoration: line-through; color: #9ca3af; }
.todo-text { flex: 1; }
.delete { background: transparent; border: none; color: #dc2626; cursor: pointer; padding: 4px 6px; border-radius: 6px; }
.delete:hover { background: #fee2e2; }
#count { margin: 12px 0 0; color: #6b7280; font-size: 13px; }",
  "scripts": [
    "const todoState = state;
if (!todoState.todos) {
  todoState.todos = [
    { id: 't1', text: 'Book train tickets', done: false },
    { id: 't2', text: 'Reserve a hotel', done: false },
    { id: 't3', text: 'Plan Saturday hike', done: false }
  ];
}

const list = root.byId['todo-list'];
const count = root.byId['count'];
const newInput = root.byId['new-todo'];
const addBtn = root.byId['add-btn'];

const render = () => {
  const items = todoState.todos.map((todo) => {
    const li = {
      tag: 'li',
      attrs: { class: todo.done ? 'done' : '' },
      children: []
    };
    const checkbox = {
      tag: 'input',
      attrs: { type: 'checkbox', id: 'check-' + todo.id },
      on: {
        click: () => {
          const found = todoState.todos.find((x) => x.id === todo.id);
          if (found) {
            found.done = !found.done;
            render();
          }
        }
      }
    };
    if (todo.done) {
      checkbox.attrs.checked = 'checked';
    }
    const label = {
      tag: 'span',
      attrs: { class: 'todo-text' },
      text: todo.text
    };
    const deleteBtn = {
      tag: 'button',
      attrs: { class: 'delete', id: 'del-' + todo.id },
      text: 'Delete',
      on: {
        click: () => {
          todoState.todos = todoState.todos.filter((x) => x.id !== todo.id);
          render();
        }
      }
    };
    li.children.push(checkbox, label, deleteBtn);
    return li;
  });
  list.children = items;
  const left = todoState.todos.filter((x) => !x.done).length;
  count.text = left + ' of ' + todoState.todos.length + ' left';
};

newInput.on = {
  input: (e) => {
    newInput.attrs.value = e.value;
  }
};

addBtn.on = {
  click: () => {
    const text = (newInput.attrs.value || '').trim();
    if (!text) {
      return;
    }
    const id = 't-' + Date.now() + '-' + Math.random().toString(16).slice(2);
    todoState.todos.push({ id: id, text: text, done: false });
    newInput.attrs.value = '';
    render();
  }
};

render();"
  ]
}
